using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.Customers;public class EditModel(ApplicationDbContext db,IPermissionService permissions):PageModel{[BindProperty]public Customer Item{get;set;}=null!;public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Update))return Forbid();var x=await db.Customers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=x;return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Update))return Forbid();if(!ModelState.IsValid)return Page();var x=await db.Customers.SingleOrDefaultAsync(x=>x.Id==Item.Id);if(x is null)return NotFound();x.Name=Item.Name;x.Phone=Item.Phone;x.Address=Item.Address;x.OpeningBalance=Item.OpeningBalance;x.Notes=Item.Notes;await db.SaveChangesAsync();TempData["Message"]="تم تعديل العميل";return RedirectToPage("Index");}}
